function parseWorkbook(wb,filename){for(const name of wb.SheetNames){const sheet=wb.Sheets[name];if(!sheet['!ref'])continue;const range=XLSX.utils.decode_range(sheet['!ref']);if(range.e.r>10000||range.e.c>100)continue;const grid=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true,range:0});const hi=grid.findIndex(row=>['항목','내용','확인'].every(l=>row.some(v=>String(v).trim()===l)));if(hi<0)continue;const headers=grid[hi].map(v=>String(v).trim()),cols=['항목','내용','확인'].map(l=>headers.indexOf(l));const rows=grid.slice(hi+1).map((r,i)=>({label:String(r[cols[0]]??'').trim(),value:r[cols[1]]??'',status:String(r[cols[2]]??'').trim(),sourceRow:hi+i+2})).filter(r=>r.label);const labels=rows.map(r=>r.label),missing=SCHEMA.filter(f=>!labels.includes(f.label));if(missing.length)throw new Error('필수 항목 누락: '+missing.slice(0,3).map(f=>f.label).join(', '));if(new Set(labels).size!==labels.length)throw new Error('중복된 항목명이 있습니다. 항목별로 한 행만 남겨 주세요.');return {filename,sheet:name,rows,importedAt:new Date().toISOString(),mode:'upload'};}throw new Error('항목 · 내용 · 확인 열이 있는 시트를 찾지 못했습니다.');}
