function commitRegistration(){if(busy||state?.registered||pending().length||problems().length)return;busy=true;$('#confirmRegister').disabled=true;$('#confirmRegister').textContent='시연 이력 저장 중…';const before=state.registered;const createdAt=new Date().toISOString(),id='DEMO-'+createdAt.slice(0,10).replaceAll('-','')+'-'+crypto.randomUUID().slice(0,6).toUpperCase();state.registered=id;const snapshot=JSON.parse(JSON.stringify(state));history.unshift({id,createdAt,snapshot,payload:payload(snapshot)});if(!persist()){history.shift();state.registered=before;busy=false;$('#confirmRegister').disabled=false;$('#confirmRegister').textContent='ERP 등록 시연 실행 →';toast('브라우저 저장 공간이 부족합니다. 등록 시연 이력을 저장하지 못했습니다.');return;}busy=false;$('#previewDialog').close();render();toast('ERP 등록 시연이 완료되었습니다.');window.scrollTo({top:0,behavior:'smooth'});}
